const int font_cn_count = sizeof(font_cn) / sizeof(font_cn[0]);

const u8 *font_cn_lookup(unsigned int code)
{
    int lo = 0, hi = font_cn_count - 1;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        if (font_cn[mid].code == (u16)code)
            return font_cn[mid].bitmap;
        if (font_cn[mid].code < (u16)code)
            lo = mid + 1;
        else
            hi = mid - 1;
    }
    return NULL;
}
